import json

questions = []

def add(sub_cat, diff, q_text, opts, c_idx, classic, smart):
    questions.append({
        "subject": "physics",
        "category": "mechanics",
        "sub_category": sub_cat,
        "difficulty": diff,
        "question_text": q_text,
        "image_url": None,
        "option_1": opts[0],
        "option_2": opts[1],
        "option_3": opts[2],
        "option_4": opts[3],
        "correct_option_index": c_idx,
        "classic_solution": classic,
        "smart_shortcut": smart
    })

